{
  "schemaVersion": 1, "id": "general-coding", "version": "0.1.0", "description": "General coding guidance; alternative Python authoring provider",
  "host": { "os": ["linux"], "arch": ["x64", "arm64"] },
  "preparation": { "granularity": "capability" },
  "permissions": { "filesystem": "package-state-and-workspace", "network": false },
  "provides": [{ "id": "python.author", "interfaceVersion": 1, "kind": "guidance", "description": "Python 编写：明确需求、小步实现、编写测试", "instructions": "AUTHOR.md", "tools": [] }],
  "requires": [],
  "lifecycle": { "runtime": "node", "entry": "worker.mjs" }
}

import { rm } from 'node:fs/promises';
let text = '';
for await (const chunk of process.stdin) text += chunk;
const request = JSON.parse(text);
let response;
if (request.operation === 'check') response = { capabilities: { 'python.author': { status: 'ready', checks: [{ name: 'bundled_guidance', passed: true }] } } };
else if (request.operation === 'prepare') response = { prepared: request.requested };
else if (request.operation === 'release') { await rm(request.taskDir, { recursive: true, force: true }); response = { released: true }; }
else throw new Error('Guidance package has no executable tools');
process.stdout.write(JSON.stringify(response));
